Path _p(List<List<double>> curves) {
  final p = Path()..fillType = PathFillType.evenOdd;
  for (final c in curves) {
    var i = 0;
    while (i < c.length) {
      final op = c[i++];
      if (op == 0) {
        p.moveTo(c[i++], c[i++]);
      } else if (op == 1) {
        p.lineTo(c[i++], c[i++]);
      } else {
        p.cubicTo(c[i++], c[i++], c[i++], c[i++], c[i++], c[i++]);
      }
    }
    p.close();
  }
  return p;
}

